/* ATP SCHOOL — cours approfondis de 6e
 * Rédactions pédagogiques originales construites à partir des intitulés
 * de la progression de 6e. Chaque fiche comprend explication, démarche,
 * exemple contextualisé, exercices corrigés et auto-évaluation.
 */
(function () {
  "use strict";
  const engine = window.ATP_LEARNING_CONTENT_6E;
  if (!engine || typeof engine.buildAll !== "function") return;
  const previousBuildAll = engine.buildAll;

  const bank = [
    {subject:"Mathématiques", match:["Nombres entiers naturels"], definition:"Un entier naturel est un nombre qui sert à dénombrer ou à ordonner : 0, 1, 2, 3… Il ne comporte ni partie décimale ni signe négatif.", objectives:["Lire, écrire et décomposer un entier naturel.","Identifier la valeur de chaque chiffre selon son rang.","Comparer, ranger et effectuer des opérations sur les entiers."], explanation:["Notre système de numération est décimal : dix unités forment une dizaine, dix dizaines forment une centaine et dix centaines forment un millier. Chaque rang vaut dix fois le rang situé immédiatement à sa droite.","Dans 62 405, le 6 représente 60 000, le 2 représente 2 000, le 4 représente 400 et le 5 représente 5 unités. Le zéro indique qu'il n'y a aucune dizaine : il conserve la place des autres chiffres.","Pour comparer deux entiers, on regarde d'abord leur nombre de chiffres. Si ce nombre est identique, on compare les chiffres de gauche à droite jusqu'à trouver une différence. Pour ranger plusieurs nombres, on applique cette règle successivement.","L'addition calcule une somme, la soustraction une différence, la multiplication un produit et la division un partage ou un groupement. Une opération doit répondre à la question posée, pas être choisie au hasard.","On peut contrôler un calcul : une soustraction se vérifie par une addition ; une multiplication peut se vérifier par une division lorsque celle-ci est exacte."], example:"Une école reçoit 24 cartons contenant chacun 18 cahiers. Le nombre total est 24 × 18 = 432 cahiers. On peut contrôler l'ordre de grandeur : 24 × 20 vaut 480, donc 432 est un résultat plausible.", method:["Repère ce que représente le nombre dans l'énoncé.","Place chaque chiffre dans son rang : unités, dizaines, centaines, milliers…","Pour comparer, commence par le chiffre le plus à gauche.","Choisis l'opération qui correspond à la situation, pose-la en alignant les rangs et calcule.","Relis la question et vérifie que l'unité de la réponse est correcte."], vocabulary:["Chiffre : symbole de 0 à 9.","Nombre : quantité écrite avec un ou plusieurs chiffres.","Rang : position d'un chiffre dans un nombre.","Somme, différence, produit et quotient : résultats des quatre opérations."], essential:"La valeur d'un chiffre dépend de sa position. Dix unités d'un rang forment une unité du rang suivant. Il faut choisir l'opération adaptée et contrôler le résultat.", exercises:[["Décompose 73 508 sous forme additive.","73 508 = 70 000 + 3 000 + 500 + 8."],["Compare 8 095 et 8 509.","8 095 < 8 509 : les milliers sont égaux, mais 0 centaine est inférieur à 5 centaines."],["Une coopérative achète 16 paquets de 25 cahiers. Combien de cahiers achète-t-elle ?","16 × 25 = 400. La coopérative achète 400 cahiers."],["Une bibliothèque possède 735 livres et en reçoit 268. Combien en possède-t-elle maintenant ?","735 + 268 = 1 003 livres."]]},
    {subject:"Mathématiques", match:["Droites et points"], definition:"Un point indique une position. Une droite est une ligne illimitée dans les deux sens. Une demi-droite possède une origine et se prolonge dans un seul sens. Un segment est limité par deux extrémités.", objectives:["Nommer et placer des points.","Distinguer droite, demi-droite et segment.","Tracer et mesurer un segment à la règle graduée."], explanation:["Un point se désigne par une lettre majuscule : A, B ou O. Il n'a ni longueur ni largeur ; il indique seulement une position.","La droite passant par A et B se note (AB). Elle se prolonge sans fin des deux côtés. La demi-droite [AB) commence en A, passe par B et continue au-delà de B.","Le segment [AB] est la partie de droite comprise entre A et B. Il possède deux extrémités et une longueur que l'on peut mesurer en centimètres ou en millimètres.","Deux droites sécantes se coupent en un point appelé intersection. Deux droites parallèles d'un même plan ne se rencontrent jamais, même si on les prolonge."], example:"Si A et B sont deux points distants de 5 cm, le segment [AB] mesure 5 cm. La droite (AB), elle, n'a pas de longueur finie.", method:["Place les points avec de petites croix et écris leurs lettres à côté.","Pour tracer une droite, aligne la règle sur deux points puis prolonge le trait des deux côtés.","Pour mesurer un segment, place le zéro de la règle sur une extrémité et lis la graduation à l'autre extrémité.","Écris toujours l'unité de mesure."], vocabulary:["Point, droite, demi-droite, segment, extrémité, intersection, droites sécantes, droites parallèles."], essential:"Les notations sont différentes : (AB) désigne une droite, [AB) une demi-droite et [AB] un segment.", exercises:[["Comment note-t-on la droite passant par A et B ?","On la note (AB), avec des parenthèses."],["Quelle est la différence entre [AB] et (AB) ?","[AB] est limité par A et B ; (AB) se prolonge indéfiniment dans les deux sens."],["Trace un segment [CD] de 6 cm.","À la règle, place C au zéro et D à la graduation 6 cm, puis vérifie la mesure."],["Deux droites se coupent en O. Comment les appelle-t-on ?","Ce sont deux droites sécantes et O est leur point d'intersection."]]},
    {subject:"Mathématiques", match:["Nombres décimaux relatifs"], definition:"Un nombre décimal relatif est un nombre décimal accompagné d'un signe positif (+) ou négatif (−). Il permet notamment de représenter une position ou une variation par rapport à zéro.", objectives:["Reconnaître les nombres positifs, négatifs et zéro.","Placer des nombres relatifs sur une droite graduée.","Comparer des nombres décimaux relatifs."], explanation:["Zéro sépare les nombres négatifs des nombres positifs. Les nombres positifs sont situés à droite de zéro sur une droite graduée ; les nombres négatifs sont à gauche.","Sur une droite graduée, les nombres augmentent toujours de gauche à droite. Ainsi, −2 est supérieur à −5, car −2 est situé plus à droite et plus proche de zéro.","Le signe + peut être écrit devant un nombre positif, mais il est souvent omis : +4 et 4 désignent le même nombre. Le signe − doit être conservé pour un nombre négatif.","Les nombres opposés ont la même distance à zéro mais des signes contraires : +3 et −3 sont opposés."], example:"À Abidjan, une température fictive de +4 °C est supérieure à −2 °C. Sur la droite graduée, +4 se trouve à droite de −2.", method:["Trace une droite et choisis une graduation régulière.","Place zéro comme origine.","Place les nombres positifs à droite et les nombres négatifs à gauche.","Pour comparer, repère lequel est le plus à droite."], vocabulary:["Nombre relatif, signe, positif, négatif, origine, droite graduée, opposé."], essential:"Sur une droite graduée, aller vers la droite signifie aller vers des nombres plus grands. Parmi deux nombres négatifs, le plus proche de zéro est le plus grand.", exercises:[["Range −3 ; +2 ; 0 ; −1 dans l'ordre croissant.","−3 < −1 < 0 < +2."],["Quel nombre est le plus grand : −7 ou −4 ? Explique.","−4 est le plus grand : il est plus proche de zéro et se situe à droite de −7."],["Donne l'opposé de +6 puis celui de −2,5.","L'opposé de +6 est −6 ; l'opposé de −2,5 est +2,5."],["Sur une droite graduée, où place-t-on −1,5 ?","À gauche de zéro, à une distance de 1,5 unité de l'origine."]]},
    {subject:"Mathématiques", match:["Segment"], definition:"Un segment est une partie de droite limitée par deux points appelés extrémités. Sa longueur est une mesure exprimée dans une unité.", objectives:["Reconnaître les extrémités d'un segment.","Tracer un segment de longueur donnée.","Mesurer et comparer des longueurs."], explanation:["Le segment [AB] commence au point A et se termine au point B. Contrairement à une droite, il ne se prolonge pas au-delà de ses extrémités.","La longueur du segment [AB] se note AB et se mesure avec une règle graduée. Le segment est l'objet géométrique ; AB est sa longueur.","Pour comparer deux segments, on peut mesurer leurs longueurs ou les reporter à l'aide d'un compas. Deux segments sont de même longueur si leurs mesures sont égales.","Le milieu d'un segment est le point qui le partage en deux segments de même longueur."], example:"Si AB = 8 cm et M est le milieu de [AB], alors AM = MB = 4 cm.", method:["Aligne le zéro de la règle sur la première extrémité.","Repère la graduation correspondant à la longueur demandée.","Marque la seconde extrémité et nomme-la.","Pour construire un milieu, mesure la longueur puis partage-la en deux parties égales."], vocabulary:["Extrémité, longueur, règle graduée, milieu, segments égaux."], essential:"Un segment a deux extrémités et une longueur mesurable. Le milieu partage le segment en deux parties de même longueur.", exercises:[["Trace [AB] de 7 cm.","Place A au zéro de la règle et B à la graduation 7 cm."],["Un segment mesure 12 cm. Quelle est la longueur de chaque moitié si on le partage en deux parties égales ?","12 ÷ 2 = 6 cm."],["AB = 5 cm et CD = 5 cm. Que peut-on dire de ces segments ?","Ils ont la même longueur."],["Un segment mesure 9 cm. Son milieu M est placé à quelle distance de A ?","AM = 9 ÷ 2 = 4,5 cm."]]},
    {subject:"Mathématiques", match:["Cercles et disques"], definition:"Un cercle est l'ensemble des points situés à une même distance d'un point appelé centre. Le disque est la surface limitée par ce cercle.", objectives:["Identifier le centre, le rayon et le diamètre.","Tracer un cercle au compas.","Distinguer cercle et disque."], explanation:["Le centre est le point fixe à égale distance de tous les points du cercle. Cette distance constante est le rayon.","Un diamètre est un segment qui passe par le centre et dont les extrémités appartiennent au cercle. Sa longueur est égale à deux fois le rayon.","Le cercle désigne uniquement la ligne fermée. Le disque désigne la région intérieure et son bord. Cette distinction est importante en géométrie.","Tous les rayons d'un même cercle ont la même longueur. Si le rayon mesure 3 cm, le diamètre mesure 6 cm."], example:"Pour tracer un cercle de centre O et de rayon 4 cm, on ouvre le compas à 4 cm, on place sa pointe en O et on fait tourner le compas sans changer l'ouverture.", method:["Marque le centre O.","Mesure l'ouverture du compas à la longueur du rayon.","Place la pointe sèche en O.","Fais tourner le compas pour tracer le cercle.","Vérifie que le diamètre vaut deux fois le rayon."], vocabulary:["Centre, rayon, diamètre, cercle, disque, compas."], essential:"Le diamètre est le double du rayon : d = 2 × r. Le cercle est le contour ; le disque est la surface intérieure.", exercises:[["Un cercle a un rayon de 5 cm. Quel est son diamètre ?","d = 2 × 5 = 10 cm."],["Un diamètre mesure 12 cm. Quel est le rayon ?","r = 12 ÷ 2 = 6 cm."],["Explique la différence entre cercle et disque.","Le cercle est la ligne qui forme le contour ; le disque comprend l'intérieur et le contour."],["Décris la construction d'un cercle de centre A et de rayon 2,5 cm.","Ouvrir le compas à 2,5 cm, placer la pointe en A et faire tourner le compas."]]},
    {subject:"Mathématiques", match:["Fractions"], definition:"Une fraction a/b représente a parts lorsque l'unité est partagée en b parts égales. Le dénominateur b ne peut jamais être nul.", objectives:["Identifier le numérateur et le dénominateur.","Lire, écrire et représenter une fraction.","Comparer des fractions simples et reconnaître des fractions équivalentes."], explanation:["Le dénominateur indique en combien de parts égales l'unité est partagée. Le numérateur indique combien de ces parts sont considérées.","Les parts doivent être de même taille. Partager une pizza en quatre parts inégales ne permet pas de dire qu'une part vaut un quart.","Si le numérateur est inférieur au dénominateur, la fraction est inférieure à 1. Si les deux sont égaux, elle vaut 1. Si le numérateur est supérieur au dénominateur, elle est supérieure à 1.","Deux fractions peuvent représenter la même quantité : 1/2 et 2/4 sont équivalentes. On obtient une fraction équivalente en multipliant ou divisant le numérateur et le dénominateur par un même nombre non nul.","Pour comparer deux fractions ayant le même dénominateur, on compare leurs numérateurs : 5/8 est supérieur à 3/8."], example:"Une galette est partagée en 8 parts égales. Si Awa en prend 3, elle a pris 3/8 de la galette : 3 est le numérateur et 8 le dénominateur.", method:["Identifie l'unité entière.","Compte le nombre total de parts égales : c'est le dénominateur.","Compte les parts retenues : c'est le numérateur.","Pour comparer des fractions de même dénominateur, compare les numérateurs.","Vérifie toujours que les parts sont égales."], vocabulary:["Fraction, numérateur, dénominateur, unité, part égale, fraction équivalente."], essential:"Le dénominateur indique le nombre de parts égales ; le numérateur indique le nombre de parts considérées. Le dénominateur ne peut pas être zéro.", exercises:[["Dans 5/8, indique le numérateur et le dénominateur.","Le numérateur est 5 ; le dénominateur est 8."],["Une mangue est partagée en 6 parts égales et Koffi en mange 2. Quelle fraction a-t-il mangée ?","Il a mangé 2/6 de la mangue."],["Compare 3/7 et 5/7.","3/7 < 5/7 car les dénominateurs sont égaux et 3 < 5."],["Donne une fraction équivalente à 1/2.","2/4, 3/6 ou 4/8 sont des fractions équivalentes à 1/2."]]},
    {subject:"Mathématiques", match:["Angles"], definition:"Un angle est une ouverture formée par deux demi-droites de même origine. Leur origine commune est le sommet de l'angle.", objectives:["Identifier le sommet et les côtés d'un angle.","Comparer et mesurer des angles au rapporteur.","Reconnaître les angles particuliers."], explanation:["Les deux demi-droites qui forment un angle sont ses côtés ; leur origine commune est le sommet. L'ouverture, et non la longueur des côtés, détermine la mesure de l'angle.","Un angle aigu mesure moins de 90°. Un angle droit mesure exactement 90°. Un angle obtus mesure plus de 90° et moins de 180°. Un angle plat mesure 180°.","Le rapporteur permet de mesurer un angle en degrés. Il faut placer le centre du rapporteur sur le sommet et aligner sa ligne de base sur un côté.","Pour tracer un angle de mesure donnée, on trace d'abord un côté, on place le rapporteur au sommet, on marque la graduation souhaitée puis on trace le second côté."], example:"Un angle de 45° est aigu ; un angle de 90° est droit ; un angle de 120° est obtus.", method:["Nomme le sommet et repère les deux côtés.","Place le centre du rapporteur exactement sur le sommet.","Aligne le zéro du rapporteur sur un côté.","Lis la graduation où passe le second côté.","Indique la mesure en degrés (°)."], vocabulary:["Sommet, côté, ouverture, degré, rapporteur, angle aigu, droit, obtus, plat."], essential:"Aigu : moins de 90° ; droit : 90° ; obtus : entre 90° et 180° ; plat : 180°.", exercises:[["Classe les angles de 35°, 90°, 145° et 180°.","35° est aigu ; 90° est droit ; 145° est obtus ; 180° est plat."],["Combien mesure un angle droit ?","90°."],["Pourquoi deux angles ayant des côtés de longueurs différentes peuvent-ils avoir la même mesure ?","Parce que la mesure dépend de l'ouverture entre les côtés, pas de leur longueur."],["Décris comment mesurer un angle avec un rapporteur.","Centre sur le sommet, ligne de base alignée sur un côté, lecture de la graduation au niveau de l'autre côté."]]},
    {subject:"Mathématiques", match:["Triangles"], definition:"Un triangle est un polygone qui possède trois côtés, trois sommets et trois angles.", objectives:["Reconnaître et nommer les éléments d'un triangle.","Construire un triangle à l'aide des instruments adaptés.","Identifier quelques triangles particuliers."], explanation:["Les sommets sont les points où deux côtés se rencontrent. Les côtés sont les segments qui relient les sommets. Les angles sont les ouvertures formées aux sommets.","Un triangle équilatéral possède trois côtés de même longueur. Un triangle isocèle possède au moins deux côtés de même longueur. Un triangle rectangle possède un angle droit.","Pour construire un triangle dont on connaît les trois côtés, on utilise la règle et le compas : on trace un premier côté puis deux arcs de cercle dont l'intersection donne le troisième sommet.","La somme des mesures des trois angles d'un triangle est égale à 180°. Cette propriété permet de calculer un angle lorsque les deux autres sont connus."], example:"Dans un triangle, deux angles mesurent 50° et 60°. Le troisième mesure 180° − 50° − 60° = 70°.", method:["Trace le côté de départ à la règle.","Utilise le compas pour reporter les longueurs demandées depuis les extrémités.","Marque l'intersection des arcs comme troisième sommet.","Relie les trois sommets et vérifie les longueurs."], vocabulary:["Triangle, sommet, côté, angle, équilatéral, isocèle, rectangle."], essential:"Un triangle a trois côtés. La somme de ses angles vaut 180°. Les triangles particuliers se reconnaissent par leurs côtés ou leurs angles.", exercises:[["Comment reconnaît-on un triangle équilatéral ?","Ses trois côtés ont la même longueur."],["Un triangle a deux côtés égaux. Comment peut-on le qualifier ?","Il est isocèle."],["Deux angles mesurent 40° et 80°. Calcule le troisième.","180° − 40° − 80° = 60°."],["Quel instrument permet de reporter une longueur pour construire un triangle ?","Le compas, en complément de la règle."]]},
    {subject:"Mathématiques", match:["Proportionnalité"], definition:"Deux grandeurs sont proportionnelles lorsque l'on passe de l'une à l'autre en multipliant toujours par un même nombre appelé coefficient de proportionnalité.", objectives:["Reconnaître une situation de proportionnalité.","Utiliser un tableau de proportionnalité.","Résoudre des problèmes simples de prix, quantité et durée."], explanation:["Dans une situation proportionnelle, si une quantité double, l'autre double aussi ; si elle est multipliée par trois, l'autre l'est également.","Le coefficient de proportionnalité est le nombre par lequel on multiplie une valeur de la première grandeur pour obtenir la valeur correspondante de la seconde.","Le prix de plusieurs articles identiques est proportionnel au nombre d'articles si le prix unitaire reste constant et qu'il n'y a ni remise ni frais fixes.","On peut utiliser le passage par l'unité : calculer d'abord la valeur pour une unité, puis multiplier par le nombre d'unités recherché."], example:"Un cahier coûte 250 F CFA. Trois cahiers coûtent 3 × 250 = 750 F CFA. Le prix est proportionnel au nombre de cahiers.", method:["Vérifie que les deux grandeurs évoluent avec le même multiplicateur.","Cherche le prix ou la quantité pour une unité si cela simplifie le calcul.","Multiplie par le nombre d'unités demandé.","Vérifie que la réponse est cohérente avec la situation."], vocabulary:["Grandeur, proportionnalité, coefficient, tableau, passage par l'unité."], essential:"Dans une situation proportionnelle, on multiplie toujours par le même coefficient. Le passage par l'unité est une méthode simple et fiable.", exercises:[["Un stylo coûte 150 F CFA. Combien coûtent 4 stylos au même prix unitaire ?","4 × 150 = 600 F CFA."],["2 kg de riz coûtent 1 200 F CFA. Quel est le prix de 1 kg ?","1 200 ÷ 2 = 600 F CFA."],["Une moto parcourt 60 km en 1 heure à vitesse constante. Quelle distance parcourt-elle en 3 heures ?","60 × 3 = 180 km."],["Pourquoi le prix d'une course avec un forfait fixe n'est-il pas toujours proportionnel à la distance ?","Parce que le coût comprend une partie fixe qui ne varie pas avec la distance."]]},
    {subject:"Mathématiques", match:["Figures symétriques par rapport à un point"], definition:"Deux figures sont symétriques par rapport à un point O lorsque l'une est l'image de l'autre par un demi-tour de centre O. Le point O est le centre de symétrie.", objectives:["Reconnaître une symétrie centrale.","Construire l'image d'un point par rapport à un centre.","Vérifier l'alignement et l'égalité des distances."], explanation:["Dans une symétrie centrale de centre O, le point O est le milieu du segment qui relie un point A à son image A'.","Les points A, O et A' sont alignés et OA = OA'. Le point image se trouve de l'autre côté de O, à la même distance.","Une symétrie centrale conserve les longueurs, les angles, l'alignement et la forme. La figure obtenue est la même, mais tournée d'un demi-tour.","Pour construire l'image d'une figure, on construit l'image de chacun de ses points puis on relie les points images dans le même ordre."], example:"Si OA = 3 cm, l'image A' de A par rapport au centre O se place sur la droite (AO), de l'autre côté de O, avec OA' = 3 cm.", method:["Trace la droite passant par le point A et le centre O.","Mesure la distance OA.","Reporte la même distance de l'autre côté de O pour placer A'.","Répète l'opération pour les autres sommets puis relie-les."], vocabulary:["Symétrie centrale, centre, image, point correspondant, milieu, demi-tour."], essential:"Le centre O est le milieu de [AA']. Les points A, O et A' sont alignés et OA = OA'.", exercises:[["Dans une symétrie de centre O, quelle est la position de O par rapport à A et A' ?","O est le milieu du segment [AA']."],["OA = 4 cm. Quelle est la longueur OA' ?","OA' = 4 cm."],["La symétrie centrale change-t-elle la longueur des côtés ?","Non, elle conserve les longueurs."],["Quel mouvement permet de visualiser une symétrie centrale ?","Un demi-tour de 180° autour du centre O."]]},
    {subject:"Mathématiques", match:["Parallélogramme"], definition:"Un parallélogramme est un quadrilatère dont les côtés opposés sont parallèles deux à deux.", objectives:["Reconnaître un parallélogramme.","Identifier ses côtés opposés et ses diagonales.","Utiliser quelques propriétés pour le construire et le vérifier."], explanation:["Un quadrilatère possède quatre côtés. Dans un parallélogramme, chaque paire de côtés opposés est parallèle.","Les côtés opposés d'un parallélogramme ont la même longueur. Les angles opposés ont également la même mesure.","Les diagonales d'un parallélogramme se coupent en leur milieu : leur point d'intersection est le milieu de chacune des deux diagonales.","Un rectangle, un losange et un carré sont des cas particuliers de parallélogrammes, car ils possèdent aussi deux paires de côtés opposés parallèles."], example:"Si ABCD est un parallélogramme, alors AB est parallèle à DC et AD est parallèle à BC. Les diagonales [AC] et [BD] se coupent en leur milieu.", method:["Vérifie que la figure possède quatre côtés.","Contrôle le parallélisme des côtés opposés avec une équerre ou une règle adaptée.","Repère les diagonales et leur point d'intersection.","Utilise les propriétés pour vérifier les longueurs ou construire la figure."], vocabulary:["Quadrilatère, côtés opposés, parallèles, diagonale, milieu, rectangle, losange."], essential:"Les côtés opposés sont parallèles et de même longueur. Les diagonales se coupent en leur milieu.", exercises:[["Combien de paires de côtés opposés parallèles possède un parallélogramme ?","Deux paires."],["Dans un parallélogramme, AB = 7 cm. Que vaut le côté opposé DC ?","DC = 7 cm."],["Les diagonales d'un parallélogramme se coupent en O. Que peut-on dire de O ?","O est le milieu de chacune des deux diagonales."],["Un carré est-il un parallélogramme ? Justifie.","Oui, car ses côtés opposés sont parallèles deux à deux."]]},
    {subject:"Mathématiques", match:["Statistiques"], definition:"Les statistiques permettent de recueillir, organiser, présenter et interpréter des données afin de répondre à une question.", objectives:["Lire un tableau d'effectifs.","Calculer un effectif total.","Interpréter un diagramme simple."], explanation:["Une enquête statistique commence par une question précise. On recueille ensuite les réponses auprès d'une population ou d'un échantillon.","L'effectif d'une valeur est le nombre de fois où cette valeur apparaît. L'effectif total est la somme de tous les effectifs.","Un tableau organise les résultats en catégories et en nombres. Un diagramme en bâtons permet de comparer visuellement les effectifs.","Les données doivent être lues avec attention : titre, catégories, échelle et unité. Une représentation graphique peut induire en erreur si l'échelle est mal comprise."], example:"Dans une classe, 12 élèves préfèrent le football, 8 le basketball et 5 le handball. L'effectif total est 12 + 8 + 5 = 25 élèves.", method:["Définis la question de l'enquête.","Classe les réponses dans des catégories sans en oublier.","Compte l'effectif de chaque catégorie.","Additionne les effectifs pour obtenir le total.","Lis le tableau ou le graphique en tenant compte du titre et de l'échelle."], vocabulary:["Population, échantillon, donnée, effectif, effectif total, tableau, diagramme."], essential:"L'effectif indique combien de fois une réponse apparaît. L'effectif total est la somme des effectifs de toutes les catégories.", exercises:[["Une enquête donne 9, 7 et 4 réponses dans trois catégories. Quel est l'effectif total ?","9 + 7 + 4 = 20 réponses."],["Dans une classe de 30 élèves, 18 sont des filles. Combien sont des garçons ?","30 − 18 = 12 garçons."],["Pourquoi faut-il lire l'échelle d'un diagramme ?","Pour interpréter correctement la hauteur des barres et ne pas confondre les valeurs."],["Dans un tableau, une catégorie a un effectif de 0. Qu'est-ce que cela signifie ?","Aucune réponse ne correspond à cette catégorie."]]},
    {subject:"Mathématiques", match:["Pavé droit et cylindre"], definition:"Le pavé droit et le cylindre droit sont des solides géométriques en trois dimensions. Ils occupent un volume.", objectives:["Reconnaître les faces, arêtes et sommets d'un pavé droit.","Identifier les bases et la surface latérale d'un cylindre.","Calculer le volume d'un pavé droit."], explanation:["Un pavé droit possède six faces rectangulaires, douze arêtes et huit sommets. Un cube est un pavé droit dont toutes les arêtes ont la même longueur.","Un cylindre droit possède deux bases circulaires parallèles et de même rayon, reliées par une surface latérale courbe. Il n'a ni sommet ni arête au sens du polyèdre.","Le volume mesure l'espace occupé par un solide. Pour un pavé droit, on multiplie la longueur par la largeur puis par la hauteur : V = L × l × h.","Les unités de volume sont cubiques : cm³, dm³ ou m³. Il faut utiliser la même unité pour les trois dimensions avant de calculer."], example:"Une boîte de 5 cm de long, 3 cm de large et 2 cm de haut a un volume de 5 × 3 × 2 = 30 cm³.", method:["Identifie le solide et ses dimensions.","Vérifie que toutes les dimensions sont exprimées dans la même unité.","Pour un pavé droit, calcule L × l × h.","Écris le résultat avec l'unité cubique correspondante."], vocabulary:["Solide, face, arête, sommet, base, hauteur, volume, centimètre cube."], essential:"Le pavé droit possède 6 faces, 12 arêtes et 8 sommets. Son volume vaut longueur × largeur × hauteur.", exercises:[["Combien de faces possède un pavé droit ?","Six faces."],["Calcule le volume d'un pavé de 4 cm × 3 cm × 5 cm.","V = 4 × 3 × 5 = 60 cm³."],["Un cube a une arête de 2 cm. Quel est son volume ?","V = 2 × 2 × 2 = 8 cm³."],["Combien de bases possède un cylindre droit ?","Deux bases circulaires parallèles et de même rayon."]]},
    {subject:"Physique-Chimie", match:["Le circuit électrique"], definition:"Un circuit électrique est un ensemble de composants reliés par des conducteurs et formant une boucle permettant au courant électrique de circuler lorsque le circuit est fermé.", objectives:["Identifier les éléments d'un circuit simple.","Distinguer circuit ouvert et circuit fermé.","Réaliser et représenter un montage simple en respectant les consignes de sécurité."], explanation:["Un circuit simple peut comporter un générateur (pile), des fils conducteurs et un récepteur (lampe). Le générateur fournit l'énergie électrique et le récepteur la transforme notamment en lumière et en chaleur.","Pour que la lampe s'allume, les composants doivent former une boucle continue : le circuit est fermé. Si un fil est débranché ou si l'interrupteur est ouvert, le circuit est interrompu et la lampe s'éteint.","Un schéma électrique utilise des symboles normalisés. Il permet de représenter clairement les connexions sans dessiner l'apparence réelle des objets.","Un matériau conducteur laisse passer le courant dans les conditions du montage ; un isolant s'y oppose fortement. Les métaux sont généralement conducteurs, tandis que le plastique sec est isolant."], example:"Une pile reliée à une lampe par deux fils forme un circuit fermé si les deux bornes de la pile sont correctement reliées aux deux contacts de la lampe.", method:["Repère le générateur, le récepteur et les fils.","Vérifie que le montage est hors tension avant de le modifier.","Relie les composants pour former une boucle complète.","Ferme l'interrupteur et observe le récepteur.","Dessine le schéma avec les symboles appropriés."], vocabulary:["Circuit, générateur, pile, récepteur, lampe, conducteur, isolant, interrupteur, circuit ouvert, circuit fermé."], essential:"La lampe ne s'allume que si le circuit est fermé et correctement relié. Ne manipule jamais une installation électrique domestique pour faire une expérience.", exercises:[["Cite trois éléments d'un circuit simple.","Une pile, des fils conducteurs et une lampe."],["Pourquoi une lampe ne s'allume-t-elle pas si un fil est débranché ?","Le circuit est ouvert : la boucle n'est plus complète."],["Donne un exemple de conducteur et un exemple d'isolant.","Le cuivre est conducteur ; le plastique sec est isolant."],["À quoi sert le schéma électrique ?","À représenter les composants et leurs connexions avec des symboles conventionnels."]]},
    {subject:"Physique-Chimie", match:["Commande d’un circuit électrique"], definition:"La commande d'un circuit électrique consiste à ouvrir ou fermer le circuit à l'aide d'un dispositif tel qu'un interrupteur.", objectives:["Expliquer le rôle d'un interrupteur.","Reconnaître les positions ouverte et fermée.","Commander un récepteur dans un circuit simple."], explanation:["Un interrupteur est un organe de commande. Il permet de contrôler le passage du courant sans avoir à débrancher les fils.","Lorsque l'interrupteur est fermé, le circuit est continu et le récepteur peut fonctionner. Lorsqu'il est ouvert, le circuit est interrompu et le récepteur ne fonctionne plus.","Un bouton-poussoir ne conserve pas nécessairement sa position : selon le modèle, le contact n'est établi que pendant l'appui ou reste établi après l'appui.","La commande doit être adaptée au circuit et utilisée avec du matériel pédagogique à basse tension."], example:"Dans une lampe de poche, le bouton permet de fermer le circuit pour allumer la lampe et de l'ouvrir pour l'éteindre.", method:["Repère le dispositif de commande.","Observe sa position sans toucher aux parties conductrices.","Identifie si le circuit est ouvert ou fermé.","Explique l'état attendu du récepteur."], vocabulary:["Interrupteur, commande, contact, ouvert, fermé, récepteur."], essential:"L'interrupteur commande le circuit : fermé, il permet le passage du courant ; ouvert, il interrompt le circuit.", exercises:[["Quel est le rôle d'un interrupteur ?","Ouvrir ou fermer le circuit pour commander le récepteur."],["Que se passe-t-il lorsque l'interrupteur est ouvert ?","Le circuit est interrompu et le récepteur cesse de fonctionner."],["Pourquoi utilise-t-on un interrupteur dans une pièce ?","Pour commander l'éclairage sans débrancher les fils."],["Une lampe reste éteinte malgré une pile en bon état. Quelle vérification simple faire sur le montage pédagogique ?","Vérifier que l'interrupteur est fermé et que les connexions forment une boucle complète."]]},
    {subject:"Physique-Chimie", match:["Court-circuit"], definition:"Un court-circuit est une liaison accidentelle de très faible résistance qui détourne le courant du trajet prévu et peut provoquer un échauffement dangereux.", objectives:["Reconnaître une situation de court-circuit.","Expliquer les dangers d'un court-circuit.","Identifier le rôle d'un dispositif de protection."], explanation:["Un court-circuit peut apparaître lorsque deux conducteurs de potentiels différents sont reliés directement par un chemin non prévu, par exemple lorsque les bornes d'une pile sont mises en contact direct.","Le courant peut alors devenir très important. Les fils et les composants peuvent chauffer fortement, détériorer le matériel ou provoquer un départ de feu.","Un fusible fond lorsque le courant dépasse une valeur prévue et coupe le circuit. Un disjoncteur ouvre automatiquement le circuit en cas de défaut selon ses caractéristiques.","Il ne faut jamais provoquer volontairement un court-circuit pour observer ses effets. Les expériences se font uniquement avec du matériel pédagogique protégé et sous la surveillance de l'enseignant."], example:"Si les deux bornes d'une pile sont reliées directement par un fil, le courant contourne la lampe : le fil et la pile peuvent chauffer.", method:["Observe le schéma et repère les connexions anormales.","Vérifie si le récepteur est contourné par un conducteur direct.","Identifie le dispositif de protection prévu.","En cas d'échauffement ou d'odeur anormale, cesse la manipulation et préviens un adulte."], vocabulary:["Court-circuit, surintensité, échauffement, fusible, disjoncteur, protection."], essential:"Le court-circuit est dangereux car il peut provoquer une forte intensité et un échauffement. Les protections coupent le circuit en cas de défaut.", exercises:[["Pourquoi un court-circuit peut-il être dangereux ?","Il peut provoquer une forte intensité, un échauffement, endommager le matériel et déclencher un incendie."],["À quoi sert un fusible ?","Il coupe le circuit lorsque le courant dépasse la valeur prévue."],["Faut-il relier directement les bornes d'une pile pour tester un court-circuit ?","Non. Il ne faut jamais provoquer volontairement un court-circuit."],["Que dois-tu faire si un fil chauffe anormalement pendant une activité ?","Arrêter la manipulation sans toucher les parties dangereuses et prévenir immédiatement l'enseignant."]]},
    {subject:"Physique-Chimie", match:["Solides et liquides"], definition:"La matière peut se présenter sous différents états. Un solide possède une forme propre ; un liquide prend la forme du récipient qui le contient et possède une surface libre au repos.", objectives:["Distinguer un solide d'un liquide.","Décrire leur forme et leur volume.","Classer des matériaux à partir d'observations."], explanation:["Un solide conserve sa forme lorsqu'on le déplace d'un récipient à un autre. Il peut être rigide, comme une pierre, ou déformable, comme une éponge ; la propriété importante est qu'il ne s'écoule pas comme un liquide.","Un liquide s'écoule et prend la forme du récipient. Au repos, sa surface libre est horizontale. Une quantité donnée de liquide conserve son volume dans les conditions usuelles, même si sa forme change.","Certains solides sont divisés en petits grains, comme le sable ou le riz. Chaque grain est solide, même si l'ensemble peut s'écouler et prendre la forme du récipient.","Pour identifier un état, on observe le comportement de la matière sans la goûter ni la manipuler dangereusement."], example:"L'eau versée d'une bouteille dans un verre change de forme mais conserve approximativement le même volume ; un caillou garde sa forme.", method:["Observe la matière dans son récipient.","Transvase une petite quantité avec du matériel adapté.","Observe si elle garde sa forme ou prend celle du récipient.","Compare le comportement avec celui d'un solide connu."], vocabulary:["Matière, solide, liquide, forme propre, volume, surface libre, écoulement."], essential:"Un solide possède une forme propre. Un liquide s'écoule et prend la forme du récipient, tout en conservant son volume.", exercises:[["Classe la pierre, l'eau et l'huile selon leur état.","La pierre est solide ; l'eau et l'huile sont liquides."],["Pourquoi l'eau prend-elle la forme du verre ?","Parce qu'un liquide prend la forme du récipient qui le contient."],["Le sable est-il un liquide ?","Non. Chaque grain de sable est un solide, même si le sable en tas peut s'écouler."],["Quelle propriété permet de distinguer un liquide d'un solide rigide ?","Le liquide s'écoule et prend la forme du récipient ; le solide garde sa forme propre."]]},
    {subject:"Physique-Chimie", match:["Les gaz"], definition:"Un gaz est un état de la matière qui n'a ni forme propre ni volume propre. Il occupe tout l'espace disponible dans le récipient qui le contient.", objectives:["Reconnaître l'état gazeux.","Mettre en évidence que l'air occupe un espace.","Décrire quelques propriétés des gaz."], explanation:["Un gaz se répartit dans tout le volume disponible. Il prend la forme du récipient et peut être comprimé, c'est-à-dire que son volume peut diminuer sous l'effet d'une pression.","L'air est un mélange de gaz. Même s'il est invisible, il occupe de l'espace et peut exercer une pression.","Une seringue bouchée contenant de l'air permet de sentir une résistance lorsqu'on pousse le piston : l'air emprisonné se comprime, mais il occupe toujours un volume.","Un gaz peut être dangereux s'il est toxique, inflammable ou s'il s'accumule dans un espace fermé. Il ne faut jamais inhaler volontairement un gaz inconnu."], example:"Un ballon se gonfle parce que l'air introduit à l'intérieur occupe de l'espace et exerce une pression sur la paroi.", method:["Observe le récipient avant et après l'introduction du gaz.","Cherche une expérience sûre montrant que le gaz occupe un espace.","Compare gaz, liquide et solide selon forme et volume.","Respecte les consignes de sécurité et ne respire jamais un gaz de laboratoire."], vocabulary:["Gaz, air, volume, pression, compression, récipient."], essential:"Un gaz occupe tout l'espace disponible, n'a ni forme ni volume propres et peut être comprimé.", exercises:[["Pourquoi un ballon gonflé devient-il plus volumineux ?","Parce que l'air introduit occupe l'espace intérieur et exerce une pression sur la paroi."],["L'air est-il de la matière même s'il est invisible ?","Oui. Il occupe un espace et possède une masse."],["Un gaz a-t-il une forme propre ?","Non, il prend la forme du récipient."],["Que signifie comprimer un gaz ?","Réduire le volume qu'il occupe en exerçant une pression."]]},
    {subject:"Physique-Chimie", match:["Température d’un corps"], definition:"La température est une grandeur physique qui indique l'état thermique d'un corps. Elle se mesure avec un thermomètre et s'exprime notamment en degrés Celsius (°C).", objectives:["Distinguer température et sensation de chaud ou de froid.","Utiliser un thermomètre correctement.","Lire et exprimer une température en °C."], explanation:["La sensation de chaud ou de froid dépend aussi de notre peau et de l'environnement. Elle ne remplace pas une mesure objective : deux personnes peuvent ressentir différemment le même objet.","Le thermomètre comporte une échelle graduée. On lit la valeur au niveau indiqué par le liquide ou l'affichage, en respectant l'unité.","Pour mesurer la température d'un liquide, on place le capteur dans le liquide sans toucher le fond ni les parois, puis on attend que la valeur se stabilise.","La température peut augmenter ou diminuer. Une hausse signifie que le corps se réchauffe ; une baisse signifie qu'il se refroidit."], example:"Si un thermomètre indique 28 °C dans une salle, la température mesurée est de vingt-huit degrés Celsius, même si chacun peut ressentir différemment l'ambiance.", method:["Choisis un thermomètre adapté à la mesure.","Place-le correctement sans danger.","Attends la stabilisation de l'indication.","Lis la graduation à hauteur des yeux et écris la valeur avec °C."], vocabulary:["Température, thermomètre, degré Celsius, mesure, réchauffement, refroidissement."], essential:"La température se mesure avec un thermomètre. La sensation de chaud ou de froid ne suffit pas pour connaître une valeur exacte.", exercises:[["Quel instrument mesure la température ?","Le thermomètre."],["Que signifie 32 °C ?","Une température de trente-deux degrés Celsius."],["Pourquoi ne faut-il pas se fier uniquement à sa main pour comparer deux températures ?","La sensation dépend de la personne et de l'état de la peau ; le thermomètre donne une mesure."],["Que faut-il attendre avant de lire un thermomètre dans un liquide ?","Il faut attendre que l'indication se stabilise."]]},
    {subject:"Physique-Chimie", match:["Constituants de l’air"], definition:"L'air est un mélange de gaz invisible qui entoure la Terre. Il est constitué principalement de diazote et de dioxygène, avec de faibles proportions d'autres gaz.", objectives:["Savoir que l'air est un mélange de gaz.","Identifier le diazote et le dioxygène comme constituants principaux.","Comprendre le rôle du dioxygène dans la respiration et la combustion."], explanation:["L'air sec contient environ 78 % de diazote et 21 % de dioxygène. Le reste est constitué principalement d'argon, de dioxyde de carbone et d'autres gaz en très petites proportions. La vapeur d'eau varie selon les conditions.","Le dioxygène est nécessaire à la respiration de nombreux êtres vivants et intervient dans les combustions. Le diazote est le constituant majoritaire de l'air, mais il ne permet pas à une flamme ordinaire d'entretenir la combustion.","L'air n'est pas un corps pur : c'est un mélange, car plusieurs gaz y sont présents ensemble.","La qualité de l'air peut être altérée par les fumées, les poussières et certains gaz polluants. Aérer les pièces et limiter les fumées contribue à protéger la santé."], example:"Une bougie allumée sous un récipient fermé finit par s'éteindre lorsque le dioxygène disponible ne suffit plus à entretenir la combustion.", method:["Retenir que l'air est un mélange.","Identifier le diazote comme gaz majoritaire et le dioxygène comme gaz indispensable à la combustion ordinaire.","Relier les observations expérimentales au rôle du dioxygène.","Ne réalise jamais d'expérience de combustion sans encadrement."], vocabulary:["Air, mélange, diazote, dioxygène, dioxyde de carbone, combustion, pollution."], essential:"L'air contient environ 78 % de diazote et 21 % de dioxygène. Le dioxygène intervient dans la respiration et la combustion.", exercises:[["L'air est-il un corps pur ou un mélange ?","C'est un mélange de plusieurs gaz."],["Quel est le gaz majoritaire de l'air ?","Le diazote, environ 78 %."],["Quel gaz de l'air permet à une flamme ordinaire de brûler ?","Le dioxygène."],["Cite deux sources possibles de pollution de l'air.","Les fumées des véhicules, les fumées de combustion, certaines poussières ou émissions industrielles."]]},
    {subject:"Physique-Chimie", match:["Changements d’état de l’eau"], definition:"Un changement d'état est le passage d'une substance d'un état physique à un autre. L'eau peut passer entre les états solide, liquide et gazeux.", objectives:["Nommer les changements d'état de l'eau.","Décrire les effets du chauffage et du refroidissement.","Relier les changements d'état à des situations quotidiennes."], explanation:["La fusion est le passage de la glace à l'eau liquide. La solidification est le passage de l'eau liquide à la glace.","La vaporisation est le passage du liquide au gaz. Elle comprend notamment l'évaporation, qui se produit à la surface et peut avoir lieu à différentes températures, et l'ébullition, qui se produit dans tout le liquide à une température donnée pour une pression donnée.","La liquéfaction (ou condensation) est le passage de la vapeur d'eau à l'état liquide. La formation de gouttelettes sur une bouteille froide en est un exemple.","Lors d'un changement d'état d'un corps pur, la température reste constante pendant le changement si la pression est maintenue constante. La matière change d'état, mais reste de l'eau."], example:"Au soleil, une flaque diminue parce qu'une partie de l'eau s'évapore. Dans un congélateur, l'eau liquide se solidifie et devient de la glace.", method:["Identifie l'état initial et l'état final.","Détermine si le corps reçoit de la chaleur ou se refroidit.","Choisis le nom exact du changement d'état.","Explique le phénomène avec un exemple de la vie courante."], vocabulary:["Fusion, solidification, vaporisation, évaporation, ébullition, liquéfaction, condensation."], essential:"Solide vers liquide : fusion. Liquide vers solide : solidification. Liquide vers gaz : vaporisation. Gaz vers liquide : liquéfaction.", exercises:[["Comment appelle-t-on le passage de la glace à l'eau ?","La fusion."],["Comment appelle-t-on le passage de l'eau liquide à la glace ?","La solidification."],["La buée sur une bouteille froide correspond à quel changement d'état ?","À la liquéfaction ou condensation de la vapeur d'eau en gouttelettes."],["Une flaque sèche au soleil. Quel phénomène se produit ?","L'évaporation de l'eau liquide."]]},
    {subject:"Physique-Chimie", match:["Combustion d’un solide"], definition:"Une combustion est une transformation chimique au cours de laquelle un combustible réagit avec un comburant, souvent le dioxygène de l'air, en libérant de l'énergie.", objectives:["Identifier le combustible et le comburant.","Décrire une combustion simple.","Reconnaître les produits et les dangers possibles."], explanation:["Le combustible est la matière qui brûle, par exemple le charbon ou le bois. Le comburant est le corps qui permet la combustion ; dans une combustion ordinaire, il s'agit du dioxygène de l'air.","Une combustion nécessite généralement un combustible, un comburant et une température suffisante pour démarrer. Ces trois éléments constituent le triangle du feu.","La combustion du carbone dans le dioxygène produit du dioxyde de carbone. Une combustion incomplète peut produire du monoxyde de carbone, un gaz très toxique et invisible.","Une combustion libère de l'énergie sous forme de chaleur et parfois de lumière. Elle peut produire des fumées et des gaz dangereux."], example:"Le charbon est un combustible solide. Lorsqu'il brûle dans l'air, il réagit avec le dioxygène et libère de la chaleur ; la combustion complète du carbone produit du dioxyde de carbone.", method:["Identifie la matière qui brûle.","Repère le rôle du dioxygène de l'air.","Décris les manifestations observables : chaleur, lumière, fumée éventuelle.","N'approche jamais un feu et ne réalise pas d'essai sans l'enseignant."], vocabulary:["Combustion, combustible, comburant, dioxygène, énergie, fumée, combustion complète, combustion incomplète."], essential:"Une combustion nécessite un combustible et un comburant, avec une énergie de démarrage. Elle peut dégager des gaz dangereux.", exercises:[["Dans la combustion du charbon dans l'air, quel est le combustible ?","Le charbon."],["Quel est le comburant habituel ?","Le dioxygène de l'air."],["Quel gaz très toxique peut apparaître lors d'une combustion incomplète ?","Le monoxyde de carbone."],["Pourquoi une combustion doit-elle être surveillée ?","Elle dégage de la chaleur et peut produire des fumées ou des gaz toxiques et provoquer un incendie."]]},
    {subject:"Physique-Chimie", match:["Combustion d’un gaz"], definition:"La combustion d'un gaz est une réaction chimique entre un gaz combustible et un comburant, généralement le dioxygène de l'air.", objectives:["Identifier un gaz combustible et le dioxygène.","Décrire les conditions d'une combustion gazeuse.","Connaître les risques liés aux gaz et aux flammes."], explanation:["Le gaz domestique utilisé pour la cuisson peut être combustible. Il ne brûle que lorsqu'il est mélangé au dioxygène dans des proportions adaptées et qu'une source d'allumage est présente.","Une combustion complète du gaz produit notamment du dioxyde de carbone et de la vapeur d'eau. Une combustion incomplète peut produire du monoxyde de carbone, qui est dangereux.","Une flamme bleue indique généralement une combustion plus complète qu'une flamme jaune lumineuse, mais la couleur seule ne garantit jamais l'absence de danger.","Une fuite de gaz peut former un mélange explosif avec l'air. En cas d'odeur de gaz, il faut éviter toute flamme et tout interrupteur électrique, s'éloigner et prévenir un adulte ou les services compétents."], example:"Un brûleur de cuisinière bien réglé mélange le gaz et l'air pour obtenir une combustion régulière. Une mauvaise combustion peut produire du monoxyde de carbone.", method:["Identifie le gaz combustible et le comburant.","Distingue combustion complète et incomplète.","Associe les produits de combustion aux dangers possibles.","Applique les consignes de sécurité sans manipuler l'installation."], vocabulary:["Gaz combustible, dioxygène, flamme, combustion complète, combustion incomplète, monoxyde de carbone, fuite."], essential:"La combustion d'un gaz nécessite du dioxygène. Une combustion incomplète peut produire du monoxyde de carbone, dangereux et invisible.", exercises:[["Quel gaz de l'air permet la combustion d'un gaz combustible ?","Le dioxygène."],["Quel gaz toxique peut être produit par une combustion incomplète ?","Le monoxyde de carbone."],["Que faire si l'on sent une forte odeur de gaz dans une pièce ?","Ne pas allumer de flamme ni actionner d'interrupteur, s'éloigner et prévenir immédiatement un adulte ou les secours compétents."],["Pourquoi faut-il ventiler correctement un appareil à combustion ?","Pour assurer l'apport d'air nécessaire et évacuer les produits de combustion."]]},
    {subject:"Physique-Chimie", match:["Dangers des combustions"], definition:"Les combustions peuvent provoquer des brûlures, des incendies et des intoxications par inhalation de fumées ou de gaz toxiques.", objectives:["Identifier les principaux dangers des combustions.","Reconnaître le risque du monoxyde de carbone.","Adopter des comportements de prévention."], explanation:["La chaleur et les flammes peuvent brûler la peau et enflammer des objets proches. Les vêtements amples, papiers et liquides inflammables doivent être éloignés des sources de chaleur.","Les fumées contiennent des particules et parfois des gaz toxiques. Le monoxyde de carbone est particulièrement dangereux : il est incolore, inodore et peut provoquer une intoxication grave.","Une mauvaise ventilation, un appareil mal entretenu ou une combustion incomplète augmentent les risques d'intoxication. Il faut faire entretenir les appareils par des personnes qualifiées et ne jamais boucher les aérations.","En cas d'incendie, il faut donner l'alerte, évacuer sans prendre de risques et appeler les secours. Il ne faut pas retourner dans un bâtiment enfumé."], example:"Un brasero utilisé dans une pièce fermée peut produire du monoxyde de carbone et provoquer une intoxication mortelle. Il ne doit jamais être utilisé dans un espace clos.", method:["Repère la source de combustion et les personnes exposées.","Éloigne les matières inflammables.","Assure une ventilation adaptée aux appareils conçus pour être utilisés dans ce lieu.","En cas de fumée ou de malaise, évacue et alerte les secours."], vocabulary:["Brûlure, incendie, fumée, intoxication, monoxyde de carbone, ventilation, prévention."], essential:"Ne jamais utiliser un brasero ou un appareil de combustion non prévu pour l'intérieur dans une pièce fermée. En cas de danger, évacuer et alerter.", exercises:[["Pourquoi le monoxyde de carbone est-il particulièrement dangereux ?","Il est invisible et inodore ; on peut l'inhaler sans s'en rendre compte."],["Cite deux moyens de prévention des intoxications liées aux combustions.","Entretenir les appareils par des professionnels et maintenir les ventilations non obstruées."],["Que faire en cas d'incendie dans un bâtiment ?","Alerter, évacuer sans prendre de risques et appeler les secours."],["Peut-on utiliser un brasero dans une chambre fermée ?","Non, car il peut produire du monoxyde de carbone et provoquer une intoxication grave."]]},
    {subject:"Physique-Chimie", match:["Volume d’un liquide"], definition:"Le volume mesure l'espace occupé par un corps. Le volume d'un liquide se mesure avec un récipient gradué et s'exprime en litres ou en millilitres.", objectives:["Lire une graduation de volume.","Utiliser une éprouvette graduée en sécurité.","Convertir des litres en millilitres."], explanation:["Le litre (L) et le millilitre (mL) sont des unités courantes de volume. Un litre correspond à 1 000 millilitres ; un demi-litre correspond à 500 millilitres.","Une éprouvette graduée comporte des traits qui indiquent des volumes. Pour lire correctement, on place les yeux à la hauteur de la surface du liquide et on lit la graduation au bas du ménisque pour l'eau.","La forme du récipient ne change pas le volume d'une quantité de liquide : 250 mL d'eau restent 250 mL lorsqu'on les verse dans un récipient plus large.","Il ne faut pas confondre volume et masse : le volume mesure l'espace occupé ; la masse mesure la quantité de matière."], example:"Une bouteille de 1,5 L contient 1 500 mL. Si on verse 500 mL, il reste 1 000 mL, soit 1 L.", method:["Choisis un récipient gradué adapté au volume recherché.","Pose-le sur une surface horizontale.","Verse le liquide doucement.","Place tes yeux au niveau de la graduation et lis le bas du ménisque pour l'eau.","Écris la valeur avec son unité."], vocabulary:["Volume, litre, millilitre, éprouvette graduée, graduation, ménisque."], essential:"1 L = 1 000 mL. Le volume d'un liquide se lit à hauteur des yeux, au bas du ménisque pour l'eau.", exercises:[["Convertis 2 L en mL.","2 × 1 000 = 2 000 mL."],["Convertis 750 mL en L.","750 mL = 0,75 L."],["Quel instrument permet de mesurer précisément le volume d'un liquide ?","Une éprouvette graduée adaptée."],["Pourquoi faut-il lire la graduation à hauteur des yeux ?","Pour éviter une erreur de lecture due à l'angle de vision."]]},
    {subject:"Physique-Chimie", match:["Masse d’un solide"], definition:"La masse mesure la quantité de matière d'un corps. Elle se mesure avec une balance et s'exprime notamment en grammes (g) ou en kilogrammes (kg).", objectives:["Distinguer masse et volume.","Mesurer la masse d'un objet avec une balance.","Utiliser les unités g et kg."], explanation:["La masse ne dépend pas de la forme de l'objet. Un morceau de pâte à modeler garde la même masse lorsqu'on le transforme, si aucune matière n'est ajoutée ou retirée.","Le kilogramme est une unité de masse ; le gramme est une unité plus petite. Un kilogramme correspond à 1 000 grammes.","Pour mesurer la masse, on place l'objet sur une balance adaptée et on lit l'indication lorsque la valeur est stabilisée. Pour un récipient contenant une matière, on peut utiliser la fonction tare pour ne mesurer que le contenu.","La masse et le volume sont deux grandeurs différentes : deux objets de même volume peuvent avoir des masses différentes."], example:"Un paquet de riz de 2 kg a une masse de 2 000 g. Un objet en métal et un objet en bois de même volume n'ont pas nécessairement la même masse.", method:["Vérifie que la balance est posée correctement et affiche zéro.","Place l'objet sans le faire tomber.","Attends la stabilisation de l'affichage.","Lis la valeur et note l'unité.","Convertis si nécessaire : 1 kg = 1 000 g."], vocabulary:["Masse, balance, gramme, kilogramme, tare, mesure."], essential:"La masse se mesure avec une balance. 1 kg = 1 000 g. Ne confonds pas masse et volume.", exercises:[["Convertis 3,5 kg en grammes.","3,5 × 1 000 = 3 500 g."],["Quel instrument mesure la masse ?","Une balance."],["Deux objets ont le même volume. Ont-ils forcément la même masse ?","Non, leur matière peut être différente et leur masse aussi."],["Pourquoi utilise-t-on la tare pour peser le contenu d'un récipient ?","Pour remettre la balance à zéro avec le récipient vide et mesurer seulement le contenu."]]},
    {subject:"SVT", match:["La formation de la graine"], definition:"Chez les plantes à fleurs, la graine se forme après la reproduction : le pollen participe à la fécondation de l'ovule contenu dans l'ovaire de la fleur.", objectives:["Identifier les principales parties d'une fleur.","Expliquer le rôle du pollen et de l'ovule.","Décrire les grandes étapes conduisant à la formation d'une graine."], explanation:["Une fleur comporte souvent des étamines, qui produisent le pollen, et un pistil, qui comprend notamment le stigmate, le style et l'ovaire. L'ovaire contient les ovules.","La pollinisation est le transport du pollen vers le stigmate. Elle peut être assurée par les insectes, le vent ou d'autres agents selon les plantes.","Après la pollinisation, le pollen peut permettre la fécondation d'un ovule. L'ovule fécondé se transforme en graine et l'ovaire peut se développer en fruit.","La graine contient un embryon végétal et des réserves nutritives, souvent protégés par une enveloppe. Elle peut rester au repos avant de germer si les conditions sont favorables."], example:"Chez le haricot, après la fécondation, les ovules deviennent des graines contenues dans une gousse, qui est le fruit.", method:["Observe une fleur sans l'abîmer inutilement.","Repère les étamines et le pistil à l'aide d'un schéma.","Suis le trajet du pollen jusqu'au stigmate.","Relie fécondation, formation de la graine et développement du fruit."], vocabulary:["Fleur, étamine, pollen, pistil, stigmate, ovaire, ovule, pollinisation, fécondation, graine, fruit."], essential:"La pollinisation permet au pollen d'atteindre le stigmate. Après fécondation, l'ovule devient une graine et l'ovaire peut devenir un fruit.", exercises:[["Quel organe de la fleur produit le pollen ?","Les étamines."],["Comment appelle-t-on le transport du pollen vers le stigmate ?","La pollinisation."],["Que devient l'ovule après la fécondation ?","Il se transforme en graine."],["Chez le haricot, où trouve-t-on les graines ?","Dans le fruit appelé gousse."]]},
    {subject:"SVT", match:["La germination des graines"], definition:"La germination est le développement de l'embryon contenu dans une graine lorsque les conditions nécessaires sont réunies.", objectives:["Définir la germination.","Identifier les conditions nécessaires à la germination.","Décrire les premières étapes du développement d'une plantule."], explanation:["Une graine viable a besoin d'eau, de dioxygène et d'une température convenable pour germer. La lumière n'est pas indispensable à la germination de toutes les graines, même si elle devient généralement importante pour la croissance après la sortie des premières feuilles.","L'eau permet à la graine de s'hydrater et déclenche la reprise de l'activité de l'embryon. Le tégument peut se ramollir et se fissurer.","La première partie qui sort est généralement la radicule, qui donnera la racine. La tigelle et la gemmule participent ensuite à la formation de la jeune tige et des premières feuilles.","Une graine noyée dans l'eau peut manquer de dioxygène et pourrir. Une graine trop sèche ne démarre pas sa germination."], example:"Pour comparer les conditions, on place des graines de haricot sur du coton humide dans un récipient aéré et d'autres sur du coton sec. Les graines humides germent si la température est adaptée.", method:["Choisis des graines saines de même espèce.","Prépare des lots en ne faisant varier qu'un seul facteur à la fois.","Observe chaque jour sans déplacer inutilement les graines.","Note la date d'apparition de la radicule et de la tigelle.","Présente les résultats dans un tableau."], vocabulary:["Germination, graine viable, tégument, embryon, radicule, tigelle, gemmule, plantule."], essential:"L'eau, le dioxygène et une température convenable sont nécessaires à la germination. La radicule apparaît généralement en premier.", exercises:[["Cite trois conditions nécessaires à la germination.","De l'eau, du dioxygène et une température convenable."],["Quelle partie de la jeune plante donne la racine ?","La radicule."],["Pourquoi une graine complètement immergée peut-elle mal germer ?","Elle peut manquer de dioxygène et finir par pourrir."],["La lumière est-elle toujours indispensable au début de la germination ?","Non, elle n'est pas indispensable à la germination de toutes les graines, mais elle devient importante pour la croissance après l'apparition des feuilles."]]},
    {subject:"SVT", match:["Reproduction chez les mammifères"], definition:"La reproduction chez les mammifères est sexuée : elle implique généralement un mâle et une femelle, la fécondation d'un ovule par un spermatozoïde et le développement de l'embryon dans l'organisme maternel.", objectives:["Reconnaître quelques caractéristiques des mammifères.","Identifier les cellules reproductrices.","Décrire les grandes étapes de la reproduction et du développement."], explanation:["Les mammifères sont des vertébrés qui possèdent notamment des poils à un moment de leur vie et dont les femelles nourrissent généralement leurs petits avec du lait produit par les glandes mammaires.","Le mâle produit des spermatozoïdes et la femelle produit des ovules. La rencontre d'un spermatozoïde et d'un ovule forme une cellule-œuf : c'est la fécondation.","Chez la plupart des mammifères étudiés au collège, l'embryon se développe dans l'utérus de la femelle pendant une durée variable appelée gestation.","Après la naissance, le jeune est nourri par sa mère et reçoit des soins parentaux. Les modalités varient selon les espèces."], example:"Chez la vache, la fécondation est suivie d'une gestation dans l'utérus. Le veau naît puis se nourrit du lait de sa mère.", method:["Identifie le mâle et la femelle de l'espèce étudiée.","Repère les cellules reproductrices et leur rôle.","Ordonne fécondation, développement embryonnaire, naissance et allaitement.","Compare les durées et les comportements sans généraliser à toutes les espèces."], vocabulary:["Mammifère, spermatozoïde, ovule, fécondation, cellule-œuf, embryon, utérus, gestation, naissance, allaitement."], essential:"La reproduction des mammifères est sexuée. Chez la plupart des espèces, l'embryon se développe dans l'utérus et le jeune est nourri par le lait maternel.", exercises:[["Quelles sont les deux cellules reproductrices ?","Le spermatozoïde et l'ovule."],["Comment appelle-t-on la période de développement de l'embryon dans l'organisme maternel ?","La gestation."],["Quel est le rôle des glandes mammaires ?","Produire le lait qui nourrit les petits."],["Remets dans l'ordre : naissance, fécondation, développement embryonnaire.","Fécondation, développement embryonnaire, naissance."]]},
    {subject:"SVT", match:["Reproduction chez les oiseaux"], definition:"Chez les oiseaux, la reproduction est sexuée et la femelle pond des œufs dans lesquels l'embryon se développe après la fécondation.", objectives:["Identifier les caractéristiques de la reproduction des oiseaux.","Décrire la structure générale d'un œuf.","Expliquer le rôle de l'incubation."], explanation:["Le mâle produit des spermatozoïdes et la femelle des ovules. Après fécondation, l'embryon se développe dans l'œuf avant la ponte ou pendant le début de son développement selon le moment de la ponte.","Un œuf d'oiseau comprend une coquille protectrice, des membranes, du blanc (albumen) et un jaune (vitellus) qui contient des réserves nutritives. L'embryon se développe à partir de la cellule-œuf fécondée.","L'incubation maintient l'œuf dans des conditions de température et d'humidité adaptées. Chez de nombreuses espèces, les parents couvent les œufs.","À l'éclosion, le jeune sort de l'œuf. Selon l'espèce, il peut être rapidement autonome ou dépendre fortement des parents pour être nourri et protégé."], example:"La poule pond des œufs fécondés si elle s'est accouplée avec un coq. La couvaison permet au poussin de se développer jusqu'à l'éclosion.", method:["Observe un schéma en coupe d'un œuf.","Identifie coquille, blanc, jaune et embryon.","Explique la fonction protectrice et nutritive de ces éléments.","Décris la succession fécondation, ponte, incubation et éclosion."], vocabulary:["Oiseau, ovule, spermatozoïde, fécondation, œuf, coquille, albumen, vitellus, incubation, éclosion."], essential:"L'embryon de l'oiseau se développe dans un œuf. Le jaune et le blanc fournissent des réserves ; la coquille protège l'ensemble.", exercises:[["Quel est le rôle de la coquille ?","Elle protège l'œuf et permet des échanges gazeux grâce à ses pores."],["Quelle partie de l'œuf contient une grande partie des réserves nutritives ?","Le jaune, appelé vitellus."],["Comment appelle-t-on la sortie du jeune de l'œuf ?","L'éclosion."],["Pourquoi l'incubation est-elle importante ?","Elle maintient des conditions adaptées au développement de l'embryon."]]},
    {subject:"SVT", match:["Facteurs de croissance"], definition:"La croissance d'une plante est l'augmentation de sa taille et de sa masse. Elle dépend de facteurs du milieu et des ressources dont la plante dispose.", objectives:["Identifier les principaux facteurs de croissance des plantes.","Distinguer les besoins en eau, lumière, air et sels minéraux.","Proposer une expérience simple pour étudier un facteur."], explanation:["L'eau est nécessaire au fonctionnement des cellules et au transport des substances dans la plante. Une plante privée d'eau se flétrit et peut mourir.","La lumière permet aux organes verts de réaliser la photosynthèse, processus par lequel la plante fabrique de la matière organique à partir d'eau et de dioxyde de carbone.","Les racines absorbent l'eau et les sels minéraux présents dans le sol. Le dioxyde de carbone de l'air est utilisé par les feuilles lors de la photosynthèse.","La température influence la vitesse des réactions biologiques. Une température trop basse ou trop élevée peut ralentir ou empêcher la croissance."], example:"Deux jeunes plants identiques sont cultivés dans des conditions semblables ; l'un reçoit de l'eau régulièrement et l'autre très peu. Le second se développe moins bien.", method:["Choisis deux plants de même espèce et de taille proche.","Maintiens les mêmes conditions sauf le facteur étudié.","Mesure la taille ou le nombre de feuilles à intervalles réguliers.","Note les observations et formule une conclusion prudente."], vocabulary:["Croissance, eau, lumière, dioxyde de carbone, sels minéraux, racines, feuilles, photosynthèse, température."], essential:"La croissance végétale dépend notamment de l'eau, de la lumière, du dioxyde de carbone, des sels minéraux et d'une température convenable.", exercises:[["Cite quatre facteurs qui influencent la croissance d'une plante.","L'eau, la lumière, les sels minéraux, le dioxyde de carbone et une température convenable."],["Quel organe absorbe principalement l'eau et les sels minéraux ?","Les racines."],["Pourquoi faut-il garder les autres conditions identiques dans une expérience ?","Pour attribuer les différences observées au seul facteur que l'on étudie."],["Quel rôle la lumière joue-t-elle dans la croissance des plantes vertes ?","Elle fournit l'énergie nécessaire à la photosynthèse."]]},
    {subject:"SVT", match:["Influence des aliments"], definition:"Les vers de terre sont des animaux qui se nourrissent de matière organique présente dans le sol. Leur croissance peut varier selon la quantité et la qualité des aliments disponibles.", objectives:["Décrire le rôle des vers de terre dans le sol.","Comprendre qu'une alimentation influence la croissance.","Comparer des résultats expérimentaux avec méthode."], explanation:["Les vers de terre ingèrent de la terre contenant des débris végétaux et de la matière organique en décomposition. Ils participent ainsi au recyclage de cette matière.","Une alimentation suffisante et adaptée apporte l'énergie et les éléments nécessaires au fonctionnement de l'organisme et à sa croissance.","Pour étudier l'influence d'un aliment, on compare plusieurs lots de vers de terre placés dans des conditions identiques, en ne faisant varier que l'alimentation étudiée.","Il faut mesurer les résultats sur une durée suffisante et éviter de conclure à partir d'une seule observation. L'humidité, la température et l'aération doivent rester comparables."], example:"Deux lots de vers de terre sont élevés dans des récipients identiques. Si un seul facteur change, par exemple le type de matière organique, on peut comparer leur évolution avec prudence.", method:["Formule une question précise sur l'alimentation.","Prépare des lots comparables et respecte le bien-être des animaux.","Ne fais varier qu'un seul facteur à la fois.","Observe et mesure régulièrement les mêmes indicateurs.","Compare les résultats et indique les limites de l'expérience."], vocabulary:["Ver de terre, matière organique, alimentation, croissance, lot témoin, expérience, observation."], essential:"La croissance dépend des ressources alimentaires, mais une expérience fiable doit contrôler aussi l'humidité, la température et les autres conditions du milieu.", exercises:[["De quoi se nourrissent principalement les vers de terre dans le sol ?","De matière organique et de débris végétaux en décomposition mélangés au sol."],["Pourquoi faut-il garder les mêmes conditions dans les deux lots ?","Pour que la différence observée puisse être reliée au facteur alimentaire étudié."],["Cite deux conditions du milieu à contrôler.","L'humidité et la température, par exemple."],["Pourquoi une seule observation ne suffit-elle pas toujours ?","Parce qu'elle peut être accidentelle ; des mesures répétées rendent la conclusion plus fiable."]]},
    {subject:"SVT", match:["Actions néfastes"], definition:"Une action néfaste sur l'environnement est une activité qui dégrade les milieux naturels, perturbe les êtres vivants ou réduit la qualité des ressources.", objectives:["Identifier des actions humaines qui dégradent l'environnement.","Expliquer leurs conséquences sur les sols, l'eau, l'air et les êtres vivants.","Proposer des comportements de prévention."], explanation:["La déforestation réduit les habitats, fragilise les sols et peut favoriser l'érosion. La disparition de la végétation rend certains terrains plus vulnérables au ruissellement.","Les déchets abandonnés peuvent polluer les sols et les eaux. Les plastiques se fragmentent et peuvent être ingérés par des animaux.","Les fumées issues des véhicules, brûlages et activités industrielles dégradent la qualité de l'air. Certaines substances polluantes peuvent nuire à la santé des êtres vivants.","L'utilisation excessive de produits chimiques, le rejet d'eaux usées non traitées et l'extraction non maîtrisée de ressources peuvent perturber les écosystèmes."], example:"Jeter des sachets plastiques dans un caniveau peut boucher l'écoulement des eaux et contribuer aux inondations pendant les fortes pluies.", method:["Observe le milieu et identifie la pression exercée.","Décris la cause de la dégradation.","Explique les conséquences sur les êtres vivants et les ressources.","Propose une action de prévention réalisable."], vocabulary:["Environnement, pollution, déforestation, érosion, déchet, écosystème, biodiversité, ressource."], essential:"Les activités humaines peuvent dégrader les sols, l'eau, l'air et les habitats. Prévenir les déchets, les pollutions et la destruction des milieux protège la santé et la biodiversité.", exercises:[["Cite deux conséquences possibles de la déforestation.","Perte d'habitats et augmentation de l'érosion des sols, par exemple."],["Pourquoi les déchets plastiques dans les caniveaux sont-ils problématiques ?","Ils peuvent bloquer l'écoulement de l'eau et contribuer aux inondations."],["Donne deux sources de pollution de l'air.","Les fumées des véhicules et les brûlages à l'air libre."],["Propose trois gestes pour protéger ton environnement scolaire.","Utiliser les poubelles, éviter le gaspillage, ne pas brûler les déchets et participer au nettoyage."]]},
    {subject:"SVT", match:["Lutte contre la dégradation"], definition:"La protection de l'environnement regroupe les actions qui préservent les ressources naturelles, la santé des populations et l'équilibre des écosystèmes.", objectives:["Proposer des moyens de lutte contre les pollutions et la dégradation.","Adopter des gestes responsables à l'école et à la maison.","Comprendre l'intérêt de l'action collective."], explanation:["La réduction des déchets commence par éviter les produits à usage unique lorsque c'est possible, réutiliser les objets et trier les déchets selon les possibilités locales.","La protection des arbres et la plantation d'espèces adaptées contribuent à maintenir les sols, fournir des habitats et améliorer le cadre de vie. Les jeunes plants doivent être entretenus pour survivre.","La protection de l'eau passe par l'usage raisonné, l'entretien des points d'eau et l'absence de rejet de déchets ou de produits polluants dans les caniveaux et cours d'eau.","Les actions collectives sont plus efficaces lorsqu'elles associent élèves, familles, communautés et autorités : sensibilisation, nettoyage organisé, gestion des déchets et respect des règles."], example:"Une classe peut organiser une journée de salubrité, installer des poubelles identifiées, sensibiliser les élèves et suivre l'état de la cour pendant plusieurs semaines.", method:["Repère un problème environnemental concret dans ton établissement.","Recherche ses causes et les personnes concernées.","Choisis une action réaliste, sûre et durable.","Répartis les responsabilités et fixe une date de suivi.","Évalue les résultats et améliore l'action si nécessaire."], vocabulary:["Protection, prévention, tri, réutilisation, salubrité, reboisement, sensibilisation, développement durable."], essential:"Protéger l'environnement demande des gestes quotidiens et des actions collectives durables : réduire les déchets, préserver l'eau, protéger les arbres et maintenir la salubrité.", exercises:[["Cite trois gestes pour réduire les déchets à l'école.","Utiliser une gourde réutilisable, trier les déchets lorsque c'est possible et ne pas jeter au sol."],["Pourquoi faut-il entretenir les jeunes arbres plantés ?","Pour favoriser leur survie grâce à l'arrosage, à la protection et au suivi."],["Propose un mini-plan de salubrité pour ta classe.","Identifier les zones sales, prévoir des poubelles, répartir les tâches, nettoyer en sécurité et vérifier régulièrement."],["Pourquoi la protection de l'environnement concerne-t-elle tout le monde ?","Parce que les ressources et les milieux sont partagés et que les conséquences de la pollution touchent toute la communauté."]]}
  ];

  function normalized(value) {
    return String(value || "").toLocaleLowerCase("fr").normalize("NFD").replace(/[\u0300-\u036f]/g, "").replace(/[’']/g, "'").replace(/\s+/g, " ").trim();
  }
  function findCourse(subject, title, section) {
    const haystack = normalized(String(title || "") + " " + String(section || ""));
    return bank.find(item => item.subject === subject && item.match.some(term => haystack.includes(normalized(term))));
  }
  function apply(target, course, title) {
    target.title = target.title || title;
    target.contentStatus = "Cours approfondi rédigé";
    target.introduction = "Mise en situation : " + course.example + " Lis les explications dans l'ordre, observe le vocabulaire, puis réalise les exercices sans regarder les corrections.";
    target.objectives = course.objectives.slice();
    target.definition = course.definition;
    target.explanation = course.explanation.slice();
    target.example = course.example;
    target.method = course.method.slice();
    target.vocabulary = course.vocabulary.slice();
    target.essential = course.essential;
    target.conclusion = "Tu maîtrises cette leçon lorsque tu peux expliquer la définition avec tes propres mots, justifier les étapes de la méthode et résoudre un exercice nouveau.";
    target.exercises = course.exercises.map((pair, index) => ({
      level: ["Compréhension", "Application", "Approfondissement", "Transfert"][index] || "Application",
      instruction: pair[0],
      correction: pair[1]
    }));
    target.quiz = [
      {question:"Quelle est la définition essentielle de cette leçon ?",answer:course.definition,explanation:"Une définition précise permet de fixer le sens de la notion."},
      {question:"Cite deux connaissances importantes à retenir.",answer:course.essential,explanation:"Ces éléments résument les règles et idées indispensables."},
      {question:"Quel exemple concret illustre cette leçon ?",answer:course.example,explanation:"L'exemple relie la connaissance à une situation observable."}
    ];
    target.revision = ["Définition : " + course.definition, "À retenir : " + course.essential, "Exemple : " + course.example];
  }
  engine.buildAll = function (raw) {
    const all = previousBuildAll(raw);
    Object.keys(all || {}).forEach(subject => {
      const lessons = all[subject] && all[subject].lessons;
      if (!Array.isArray(lessons)) return;
      lessons.forEach(lesson => {
        const course = findCourse(subject, lesson.title, lesson.section);
        if (!course) return;
        apply(lesson, course, lesson.title);
        (lesson.sessions || []).forEach(session => apply(session, course, session.title || lesson.title));
      });
    });
    return all;
  };
  engine.deepCourseVersion = "1.0";
  engine.deepCourseCount = bank.length;
})();
